//! Copies the effect table generated by Nix into `OUT_DIR`.
//!
//! The table lives in `assets/camera-effects.nix` and is generated by
//! `nix/camera-effects.nix`. This build script does NOT generate it — it only
//! locates the finished file (invariant 5), the same shape as
//! `ronoctua-syncthing`'s.

use std::{env, fs, path::PathBuf};

fn main() {
    println!("cargo:rerun-if-env-changed=RONOCTUA_CAMERA_EFFECTS_RS");
    let generated = env::var("RONOCTUA_CAMERA_EFFECTS_RS").unwrap_or_else(|_| {
        panic!(
            "RONOCTUA_CAMERA_EFFECTS_RS is not set.\n\
             \n\
             The effect table is generated by Nix out of assets/camera-effects.nix.\n\
             Enter the environment with `nix develop`, which sets the variable, or\n\
             build through the flake with `nix build`."
        )
    });
    println!("cargo:rerun-if-changed={generated}");
    let destination = PathBuf::from(env::var("OUT_DIR").expect("OUT_DIR")).join("effects.rs");
    // DELETE FIRST: the file comes from the store, read-only, and a second
    // copy over it fails with "Permission denied".
    let _ = fs::remove_file(&destination);
    fs::copy(&generated, &destination)
        .unwrap_or_else(|e| panic!("could not copy {generated} -> {destination:?}: {e}"));
}
